[patterns/application/api-microservices/PTN-APP-API-007-database-per-service-pattern.md#3-data-synchronization-strategies]

#### 3. Data Synchronization Strategies

Services maintain **local copies** of frequently accessed external data:

```mermaid
graph LR
    subgraph "Provider Service (System of Record)"
        ProviderDB[(Provider DB)]
        ProviderAPI[Provider API]
        ProviderAPI -->|Owns| ProviderDB
    end

    subgraph "Claims Service (Local Copy)"
        ClaimsDB[(Claims DB)]
        ClaimsAPI[Claims Service]
        ProviderCache[Provider Cache Table]
        ClaimsAPI -->|Owns| ClaimsDB
        ProviderCache -.->|Part of| ClaimsDB
    end

    subgraph "Analytics Service (Local Copy)"
        AnalyticsDB[(Analytics DB)]
        AnalyticsAPI[Analytics Service]
        ProviderMV[Provider Materialized View]
        AnalyticsAPI -->|Owns| AnalyticsDB
        ProviderMV -.->|Part of| AnalyticsDB
    end

    EventBus[Azure Service Bus]

    ProviderAPI -->|Publish| EventBus
    EventBus -->|ProviderUpdated Event| ClaimsAPI
    EventBus -->|ProviderUpdated Event| AnalyticsAPI

    ClaimsAPI -->|Update| ProviderCache
    AnalyticsAPI -->|Update| ProviderMV

    style ProviderDB fill:#90EE90
    style ProviderCache fill:#FFE4B5
    style ProviderMV fill:#FFE4B5
```

**Synchronization Patterns:**

**Pattern 1: Event-Driven Synchronization** (Recommended for most cases)

```csharp
// Provider Service (System of Record) - Publishes events
public class ProviderService
{
    private readonly ProviderDbContext _dbContext;
    private readonly IServiceBusClient _serviceBus;

    public async Task UpdateProviderAsync(UpdateProviderCommand cmd)
    {
        // Update system of record
        var provider = await _dbContext.Providers.FindAsync(cmd.ProviderId);
        provider.Name = cmd.Name;
        provider.SpecialtyCode = cmd.SpecialtyCode;
        await _dbContext.SaveChangesAsync();

        // Publish event for other services
        await _serviceBus.PublishAsync(new ProviderUpdatedEvent
        {
            ProviderId = provider.Id,
            Name = provider.Name,
            SpecialtyCode = provider.SpecialtyCode,
            UpdatedAt = DateTime.UtcNow
        });
    }
}

// Claims Service (Consumer) - Updates local cache
public class ProviderUpdatedEventHandler : IEventHandler<ProviderUpdatedEvent>
{
    private readonly ClaimsDbContext _dbContext;

    public async Task HandleAsync(ProviderUpdatedEvent evt)
    {
        // Update local provider cache table
        var providerCache = await _dbContext.ProviderCache.FindAsync(evt.ProviderId);

        if (providerCache == null)
        {
            providerCache = new ProviderCache { ProviderId = evt.ProviderId };
            _dbContext.ProviderCache.Add(providerCache);
        }

        providerCache.Name = evt.Name;
        providerCache.SpecialtyCode = evt.SpecialtyCode;
        providerCache.LastSyncedAt = DateTime.UtcNow;

        await _dbContext.SaveChangesAsync();
    }
}
```

**Pattern 2: API Composition** (For real-time consistency)

```java
// Claims Service - Composes data from multiple services
@RestController
public class ClaimController {
    @Autowired private ClaimRepository claimRepo;
    @Autowired private ProviderClient providerClient;  // API client
    @Autowired private MemberClient memberClient;      // API client

    @GetMapping("/claims/{claimId}")
    public ClaimDetailsResponse getClaimDetails(@PathVariable String claimId) {
        // Get claim from local database
        Claim claim = claimRepo.findById(claimId)
            .orElseThrow(() -> new NotFoundException("Claim not found"));

        // Get provider details from Provider Service API
        ProviderResponse provider = providerClient.getProvider(claim.getProviderId());

        // Get member details from Member Service API
        MemberResponse member = memberClient.getMember(claim.getMemberId());

        // Compose response
        return ClaimDetailsResponse.builder()
            .claimId(claim.getId())
            .claimAmount(claim.getAmount())
            .providerName(provider.getName())
            .providerSpecialty(provider.getSpecialtyCode())
            .memberName(member.getName())
            .memberEligibility(member.getEligibilityStatus())
            .build();
    }
}
```

**Pattern 3: Materialized View** (For analytics/reporting)

```sql
-- Analytics Service - Maintains materialized view with aggregated data
-- Scheduled refresh every 15 minutes via event-driven updates

CREATE TABLE ProviderClaimSummary (
    ProviderId UNIQUEIDENTIFIER PRIMARY KEY,
    ProviderName NVARCHAR(200),
    SpecialtyCode VARCHAR(10),
    TotalClaims INT,
    TotalAmount DECIMAL(18,2),
    AveragePaidAmount DECIMAL(18,2),
    LastClaimDate DATETIME2,
    LastRefreshedAt DATETIME2
);

-- Event handler updates materialized view
public class ClaimApprovedEventHandler : IEventHandler<ClaimApprovedEvent>
{
    private readonly AnalyticsDbContext _dbContext;

    public async Task HandleAsync(ClaimApprovedEvent evt)
    {
        // Update materialized view incrementally
        var summary = await _dbContext.ProviderClaimSummary
            .FindAsync(evt.ProviderId);

        if (summary == null)
        {
            summary = new ProviderClaimSummary
            {
                ProviderId = evt.ProviderId,
                ProviderName = evt.ProviderName
            };
            _dbContext.ProviderClaimSummary.Add(summary);
        }

        summary.TotalClaims += 1;
        summary.TotalAmount += evt.ClaimAmount;
        summary.AveragePaidAmount = summary.TotalAmount / summary.TotalClaims;
        summary.LastClaimDate = evt.ApprovedAt;
        summary.LastRefreshedAt = DateTime.UtcNow;

        await _dbContext.SaveChangesAsync();
    }
}
```

