#### Phase 2: Implement Service-Owned Database

**Step 3: Create Isolated Database Infrastructure**

**.NET Core Example - Claims Service with SQL Server:**

```csharp
// ClaimsService/appsettings.json
{
  "ConnectionStrings": {
    "ClaimsDatabase": "Server=claims-db.database.windows.net;Database=ClaimsDB;User Id=claims-service;Password={vault:claims-db-password}"
  },
  "DatabaseOptions": {
    "CommandTimeout": 30,
    "EnableRetryOnFailure": true,
    "MaxRetryCount": 3,
    "MaxRetryDelay": "00:00:05"
  }
}

// ClaimsService/Data/ClaimsDbContext.cs
using Microsoft.EntityFrameworkCore;

public class ClaimsDbContext : DbContext
{
    public ClaimsDbContext(DbContextOptions<ClaimsDbContext> options)
        : base(options)
    {
    }

    // Claims Service owns these tables exclusively
    public DbSet<Claim> Claims { get; set; }
    public DbSet<ClaimLine> ClaimLines { get; set; }
    public DbSet<AdjudicationRule> AdjudicationRules { get; set; }

    // Local cache of provider data (synced from Provider Service)
    public DbSet<ProviderCache> ProviderCache { get; set; }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Claims aggregate
        modelBuilder.Entity<Claim>(entity =>
        {
            entity.ToTable("Claims");
            entity.HasKey(e => e.ClaimId);
            entity.Property(e => e.ProviderId).IsRequired();
            entity.Property(e => e.MemberId).IsRequired();
            entity.Property(e => e.Amount).HasPrecision(18, 2);

            // Index for performance
            entity.HasIndex(e => new { e.Status, e.SubmittedAt });
            entity.HasIndex(e => e.ProviderId);
        });

        // Provider cache (not owned data, synced from Provider Service)
        modelBuilder.Entity<ProviderCache>(entity =>
        {
            entity.ToTable("ProviderCache");
            entity.HasKey(e => e.ProviderId);
            entity.Property(e => e.Name).HasMaxLength(200);
            entity.Property(e => e.LastSyncedAt).IsRequired();

            // Add comment to indicate this is cached data
            entity.HasComment("Cached provider data. System of record: Provider Service");
        });
    }
}

// ClaimsService/Startup.cs
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register Claims Service database
        services.AddDbContext<ClaimsDbContext>(options =>
            options.UseSqlServer(
                Configuration.GetConnectionString("ClaimsDatabase"),
                sqlOptions =>
                {
                    sqlOptions.EnableRetryOnFailure(
                        maxRetryCount: 3,
                        maxRetryDelay: TimeSpan.FromSeconds(5),
                        errorNumbersToAdd: null);
                    sqlOptions.CommandTimeout(30);
                }));

        // Register repositories
        services.AddScoped<IClaimRepository, ClaimRepository>();

        // Register API clients for cross-service calls
        services.AddHttpClient<IProviderClient, ProviderClient>(client =>
        {
            client.BaseAddress = new Uri(Configuration["Services:ProviderService:BaseUrl"]);
            client.Timeout = TimeSpan.FromSeconds(5);
        })
        .AddPolicyHandler(GetRetryPolicy())
        .AddPolicyHandler(GetCircuitBreakerPolicy());
    }

    private static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy()
    {
        return HttpPolicyExtensions
            .HandleTransientHttpError()
            .WaitAndRetryAsync(3, retryAttempt =>
                TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));
    }
}
```

