#### Phase 3: Implement Cross-Service Communication

**Step 4: Create API Contracts for Cross-Service Data Access**

Instead of database joins, use **API calls**:

```csharp
// ClaimsService/Clients/IProviderClient.cs
public interface IProviderClient
{
    Task<ProviderResponse> GetProviderAsync(Guid providerId);
    Task<int> GetActiveClaimsCountAsync(Guid providerId);
}

// ClaimsService/Clients/ProviderClient.cs
public class ProviderClient : IProviderClient
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<ProviderClient> _logger;

    public ProviderClient(HttpClient httpClient, ILogger<ProviderClient> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    public async Task<ProviderResponse> GetProviderAsync(Guid providerId)
    {
        try
        {
            var response = await _httpClient.GetAsync($"/api/providers/{providerId}");
            response.EnsureSuccessStatusCode();

            return await response.Content.ReadFromJsonAsync<ProviderResponse>();
        }
        catch (HttpRequestException ex)
        {
            _logger.LogError(ex, "Failed to retrieve provider {ProviderId}", providerId);
            throw new ProviderServiceException(
                $"Provider service unavailable for provider {providerId}", ex);
        }
    }
}

// ClaimsService/Services/ClaimService.cs
public class ClaimService
{
    private readonly ClaimsDbContext _dbContext;
    private readonly IProviderClient _providerClient;
    private readonly IMemberClient _memberClient;

    public async Task<Result<Claim>> SubmitClaimAsync(SubmitClaimCommand cmd)
    {
        // Validate provider exists and is active via API call
        var provider = await _providerClient.GetProviderAsync(cmd.ProviderId);
        if (!provider.IsActive)
        {
            return Result.Failure<Claim>("Provider is not active");
        }

        // Validate member eligibility via API call
        var member = await _memberClient.GetMemberAsync(cmd.MemberId);
        if (!member.IsEligible)
        {
            return Result.Failure<Claim>("Member is not eligible");
        }

        // Create claim in Claims database
        var claim = new Claim
        {
            ClaimId = Guid.NewGuid(),
            ProviderId = cmd.ProviderId,
            ProviderName = provider.Name,  // Cache provider name
            MemberId = cmd.MemberId,
            Amount = cmd.Amount,
            Status = "Pending",
            SubmittedAt = DateTime.UtcNow
        };

        _dbContext.Claims.Add(claim);
        await _dbContext.SaveChangesAsync();

        return Result.Success(claim);
    }
}
```

**Step 5: Implement Event-Driven Data Synchronization**

Publish events when data changes:

```csharp
// ProviderService/Services/ProviderService.cs
public class ProviderService
{
    private readonly ProviderDbContext _dbContext;
    private readonly IServiceBusClient _serviceBus;
    private readonly ILogger<ProviderService> _logger;

    public async Task<Result> UpdateProviderAsync(UpdateProviderCommand cmd)
    {
        var provider = await _dbContext.Providers.FindAsync(cmd.ProviderId);
        if (provider == null)
        {
            return Result.Failure("Provider not found");
        }

        // Update provider in Provider database
        provider.Name = cmd.Name;
        provider.SpecialtyCode = cmd.SpecialtyCode;
        provider.UpdatedAt = DateTime.UtcNow;

        await _dbContext.SaveChangesAsync();

        // Publish event for other services to sync their caches
        var evt = new ProviderUpdatedEvent
        {
            ProviderId = provider.ProviderId,
            Npi = provider.Npi,
            Name = provider.Name,
            SpecialtyCode = provider.SpecialtyCode,
            IsActive = provider.IsActive,
            UpdatedAt = provider.UpdatedAt
        };

        await _serviceBus.PublishAsync(evt);

        _logger.LogInformation(
            "Provider {ProviderId} updated and event published",
            provider.ProviderId);

        return Result.Success();
    }
}

// ClaimsService/EventHandlers/ProviderUpdatedEventHandler.cs
public class ProviderUpdatedEventHandler : IEventHandler<ProviderUpdatedEvent>
{
    private readonly ClaimsDbContext _dbContext;
    private readonly ILogger<ProviderUpdatedEventHandler> _logger;

    public async Task HandleAsync(ProviderUpdatedEvent evt)
    {
        try
        {
            // Update local provider cache in Claims database
            var providerCache = await _dbContext.ProviderCache
                .FindAsync(evt.ProviderId);

            if (providerCache == null)
            {
                providerCache = new ProviderCache
                {
                    ProviderId = evt.ProviderId
                };
                _dbContext.ProviderCache.Add(providerCache);
            }

            providerCache.Npi = evt.Npi;
            providerCache.Name = evt.Name;
            providerCache.SpecialtyCode = evt.SpecialtyCode;
            providerCache.IsActive = evt.IsActive;
            providerCache.LastSyncedAt = DateTime.UtcNow;

            await _dbContext.SaveChangesAsync();

            _logger.LogInformation(
                "Provider cache updated for provider {ProviderId}",
                evt.ProviderId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Failed to update provider cache for provider {ProviderId}",
                evt.ProviderId);
            throw; // Retry via message broker
        }
    }
}
