#### 2. Implement Idempotent Event Handlers

Ensure event handlers can safely process duplicate events:

```csharp
public class ProviderUpdatedEventHandler : IEventHandler<ProviderUpdatedEvent>
{
    private readonly ClaimsDbContext _dbContext;

    public async Task HandleAsync(ProviderUpdatedEvent evt)
    {
        // Check if already processed (idempotency)
        var existingCache = await _dbContext.ProviderCache
            .FindAsync(evt.ProviderId);

        // Only update if event is newer than cached data
        if (existingCache != null &&
            existingCache.LastSyncedAt >= evt.UpdatedAt)
        {
            // Event already processed or out of order, skip
            return;
        }

        // Safe to update
        if (existingCache == null)
        {
            existingCache = new ProviderCache { ProviderId = evt.ProviderId };
            _dbContext.ProviderCache.Add(existingCache);
        }

        existingCache.Name = evt.Name;
        existingCache.SpecialtyCode = evt.SpecialtyCode;
        existingCache.LastSyncedAt = DateTime.UtcNow;

        await _dbContext.SaveChangesAsync();
    }
}
```

