#### 5. Use Compensating Transactions for Failures

Implement **saga pattern** for distributed transactions:

```csharp
public class ClaimSubmissionSaga
{
    public async Task<Result> ExecuteAsync(SubmitClaimCommand cmd)
    {
        var sagaState = new ClaimSagaState();

        try
        {
            // Step 1: Reserve member eligibility
            sagaState.EligibilityId = await _memberService
                .ReserveEligibilityAsync(cmd.MemberId);

            // Step 2: Create claim
            sagaState.ClaimId = await _claimService
                .CreateClaimAsync(cmd);

            // Step 3: Notify provider
            await _notificationService
                .NotifyProviderAsync(cmd.ProviderId, sagaState.ClaimId);

            return Result.Success();
        }
        catch (Exception ex)
        {
            // Compensate in reverse order
            await CompensateAsync(sagaState);
            return Result.Failure(ex.Message);
        }
    }

    private async Task CompensateAsync(ClaimSagaState state)
    {
        if (state.ClaimId != Guid.Empty)
        {
            await _claimService.DeleteClaimAsync(state.ClaimId);
        }

        if (state.EligibilityId != Guid.Empty)
        {
            await _memberService.ReleaseEligibilityAsync(state.EligibilityId);
        }
    }
}
