#### State Contract Compliance

Each database must support **state-specific retention and reporting**:

```csharp
// ClaimsService/Compliance/DataRetentionPolicy.cs
public class DataRetentionPolicy
{
    private readonly ClaimsDbContext _dbContext;

    public async Task ApplyRetentionPolicyAsync()
    {
        var retentionPolicies = new Dictionary<string, int>
        {
            { "CA", 10 },  // California: 10 years
            { "NY", 7 },   // New York: 7 years
            { "TX", 5 },   // Texas: 5 years
            { "FL", 5 }    // Florida: 5 years
        };

        foreach (var (state, years) in retentionPolicies)
        {
            var cutoffDate = DateTime.UtcNow.AddYears(-years);

            // Archive claims older than retention period
            var claimsToArchive = await _dbContext.Claims
                .Where(c => c.StateCode == state && c.SubmittedAt < cutoffDate)
                .ToListAsync();

            if (claimsToArchive.Any())
            {
                await ArchiveClaimsAsync(claimsToArchive, state);

                // Delete from operational database after archiving
                _dbContext.Claims.RemoveRange(claimsToArchive);
                await _dbContext.SaveChangesAsync();
            }
        }
    }
}
```

