// ProviderService/service/ProviderService.java
@Service
public class ProviderService {

    @Autowired
    private ProviderRepository providerRepo;  // PostgreSQL

    @Autowired
    private ProviderSearchService searchService;  // Elasticsearch

    @Transactional
    public Provider createProvider(CreateProviderRequest request) {
        // Write to PostgreSQL (system of record)
        Provider provider = Provider.builder()
            .npi(request.getNpi())
            .name(request.getName())
            .specialtyCode(request.getSpecialtyCode())
            .credentialingStatus("Pending")
            .isActive(true)
            .createdAt(Instant.now())
            .build();

        provider = providerRepo.save(provider);

        // Sync to Elasticsearch (search index)
        ProviderSearchDocument searchDoc = ProviderSearchDocument.builder()
            .providerId(provider.getProviderId())
            .npi(provider.getNpi())
            .name(provider.getName())
            .specialtyCode(provider.getSpecialtyCode())
            .isActive(provider.getIsActive())
            .indexedAt(Instant.now())
            .build();

        searchService.indexProvider(searchDoc);

        return provider;
    }

    // Fast fuzzy search via Elasticsearch
    public SearchProvidersResponse searchProviders(String query) {
        // Use Elasticsearch for fast fuzzy matching
        List<ProviderSearchDocument> searchResults =
            searchService.fuzzySearch(query, 20);

        return new SearchProvidersResponse(searchResults);
    }

    // Structured credentialing workflow via PostgreSQL
    public Provider updateCredentialingStatus(UUID providerId, String status) {
        // Use PostgreSQL for transactional credentialing workflow
        Provider provider = providerRepo.findById(providerId)
            .orElseThrow(() -> new NotFoundException("Provider not found"));

        provider.setCredentialingStatus(status);
        provider.setUpdatedAt(Instant.now());

        return providerRepo.save(provider);
    }
}

// ProviderService/search/ProviderSearchService.java
@Service
public class ProviderSearchService {

    @Autowired
    private ElasticsearchClient esClient;

    public List<ProviderSearchDocument> fuzzySearch(String query, int size) {
        // Elasticsearch fuzzy query with relevance ranking
        SearchRequest request = SearchRequest.of(s -> s
            .index("providers")
            .query(q -> q
                .multiMatch(m -> m
                    .query(query)
                    .fields("name^3", "npi^2", "specialtyCode")  // Boost name matches
                    .fuzziness("AUTO")
                    .type(TextQueryType.BestFields)
                )
            )
            .size(size)
        );

        SearchResponse<ProviderSearchDocument> response =
            esClient.search(request, ProviderSearchDocument.class);

        return response.hits().hits().stream()
            .map(hit -> hit.source())
            .collect(Collectors.toList());
    }

    public void indexProvider(ProviderSearchDocument doc) {
        IndexRequest<ProviderSearchDocument> request = IndexRequest.of(i -> i
            .index("providers")
            .id(doc.getProviderId().toString())
            .document(doc)
        );

        esClient.index(request);
    }
}
```

**Results:**

Elasticsearch-backed provider search delivers sub-100ms fuzzy name search with relevance ranking, replacing multi-second SQL LIKE queries. The services can be deployed and scaled independently with separate schemas optimized for each workload.

