    public async Task HandleAsync(ClaimApprovedEvent evt)
    {
        // Incrementally update analytics data warehouse
        using var transaction = await _dbContext.Database.BeginTransactionAsync();

        try
        {
            // Insert into fact table
            var factClaim = new FactClaim
            {
                ClaimId = evt.ClaimId,
                ProviderKey = await GetProviderKeyAsync(evt.ProviderId),
                MemberKey = await GetMemberKeyAsync(evt.MemberId),
                ServiceDateKey = ConvertToDateKey(evt.ServiceDate),
