            _dbContext.FactClaims.Add(factClaim);

            // Update pre-aggregated summary
            var yearMonth = evt.ApprovedAt.Year * 100 + evt.ApprovedAt.Month;
            var summary = await _dbContext.ProviderClaimSummary
                .FindAsync(evt.ProviderId, evt.StateCode, yearMonth);

            if (summary == null)
            {
                summary = new ProviderClaimSummary
                {
                    ProviderId = evt.ProviderId,
                    StateCode = evt.StateCode,
                    YearMonth = yearMonth
                };
                _dbContext.ProviderClaimSummary.Add(summary);
            }

            summary.TotalClaims += 1;
            summary.TotalClaimAmount += evt.ClaimAmount;
            summary.TotalApprovedAmount += evt.ApprovedAmount;
            summary.AveragePaidAmount =
                summary.TotalApprovedAmount / summary.TotalClaims;

            await _dbContext.SaveChangesAsync();
            await transaction.CommitAsync();
        }
        catch
        {
            await transaction.RollbackAsync();
            throw;
        }
    }
}

// AnalyticsService/Services/ReportingService.cs
public class ReportingService
{
    private readonly AnalyticsDbContext _dbContext;

    public async Task<StateMonthlyReportResponse> GenerateStateMonthlyReportAsync(
        string stateCode, int year, int month)
    {
        var yearMonth = year * 100 + month;

        // Fast query against pre-aggregated summary
        var report = await _dbContext.ProviderClaimSummary
            .Where(s => s.StateCode == stateCode && s.YearMonth == yearMonth)
            .GroupBy(s => s.StateCode)
            .Select(g => new StateMonthlyReportResponse
            {
                StateCode = g.Key,
                TotalProviders = g.Count(),
                TotalClaims = g.Sum(s => s.TotalClaims),
                TotalAmount = g.Sum(s => s.TotalApprovedAmount),
                AverageClaimAmount = g.Average(s => s.AveragePaidAmount)
            })
            .FirstOrDefaultAsync();

        return report;
    }
}
